package studio.solocamera;
import android.app.*;import android.content.*;import android.graphics.*;import android.media.*;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.io.*;import org.json.*;
/** Physical gestures, legacy migration and export checks for placement/keyframe independence. */
final class MotionPlacementChecks {
 interface Action{void run()throws Exception;}
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static void ui(Instrumentation h,Action f){Throwable[] error={null};h.runOnMainSync(()->{try{f.run();}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw new RuntimeException(error[0]);}
 static Object get(Object a,String n)throws Exception{Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(a);}
 static void set(Object a,String n,Object v)throws Exception{Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);f.set(a,v);}
 static void call(Object a,String n)throws Exception{Method m=a.getClass().getDeclaredMethod(n);m.setAccessible(true);m.invoke(a);}
 static void select(EditorActivity a,long at)throws Exception{Method m=EditorActivity.class.getDeclaredMethod("selectMotionKey",long.class);m.setAccessible(true);m.invoke(a,at);}
 static void status(Instrumentation h,String s){Bundle b=new Bundle();b.putString("stage",s);h.sendStatus(0,b);}
 static void drag(View v,float dx,float dy){long down=SystemClock.uptimeMillis();float x=v.getWidth()*.4f,y=v.getHeight()*.65f;for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_MOVE,MotionEvent.ACTION_UP}){MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x+(action==MotionEvent.ACTION_DOWN?0:dx),y+(action==MotionEvent.ACTION_DOWN?0:dy),0);v.dispatchTouchEvent(e);e.recycle();}}
 static void seek(EditorActivity a,long at)throws Exception{EditorLivePreview v=(EditorLivePreview)get(a,"livePreview");v.pause();v.seekTo(at);set(a,"position",at);}
 static EditorProject current(EditorActivity a)throws Exception{return (EditorProject)get(a,"project");}
 static void save(File dir,String name,Bitmap b)throws Exception{try(FileOutputStream out=new FileOutputStream(new File(dir,name))){b.compress(Bitmap.CompressFormat.PNG,100,out);}}
 static EditorProject.Clip legacy(boolean extra)throws Exception{EditorProject.Clip c=EditorTitlePresets.create(40,5000);long[] times={0,550,4450,5000};for(int i=0;i<4;i++){EditorMotion.Key k=new EditorMotion.Key();k.at=times[i];k.y=i==0?-.55:-.5;k.alpha=i==0||i==3?0:1;if(i==0){k.x1=.16;k.y1=1;k.x2=.3;k.y2=1;}c.keys.add(k);}if(extra){EditorMotion.Key k=new EditorMotion.Key();k.at=1200;k.x=.22;k.y=-.35;c.keys.add(k);c.keys.sort((a,b)->Long.compare(a.at,b.at));}JSONObject j=c.json();j.remove("titleMotion");return EditorProject.Clip.from(j);}
 static void run(Instrumentation h,Bundle result)throws Exception{
  EditorActivity a=(EditorActivity)h.startActivitySync(new Intent(h.getTargetContext(),EditorActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));EditorFonts.init(a);File dir=new File(a.getCacheDir(),"motion-placement-qa");dir.mkdirs();EditorProject project=new EditorProject();project.id="55555555-5555-4555-8555-555555555550";project.name="Placement QA";project.aspect=2;project.height=720;EditorProject.Caption item=new EditorProject.Caption();item.style=EditorTitlePresets.create(40,5000);item.at=1000;item.end=6000;item.track=0;project.captions.add(item);
  try{
   status(h,"Legacy migration and independent preset motion");EditorProject.Clip migrated=legacy(false);check(migrated.titleMotion==1&&migrated.keys.isEmpty(),"Old generated keys were not separated");EditorProject.Clip retained=legacy(true);check(retained.keys.size()==1&&retained.keys.get(0).at==1200&&retained.titleMotion==1,"Migration discarded user keyframes");EditorMotion.place(retained,.4,-.2,2000,true);check(retained.keys.size()==1&&Math.abs(EditorMotion.sampleBase(retained,4000,true).x-.4)<.0001,"Whole-object movement added a key");for(int id=0;id<EditorTitlePresets.NAMES.length;id++){EditorProject.Clip c=EditorTitlePresets.create(id,5000);check(c.keys.isEmpty(),"Preset contains manual keys "+id);EditorMotion.place(c,.05,-.2,1500,true);EditorMotion.scale(c,1.1,1500,true);for(long t:new long[]{900,1500,3000,4000}){EditorMotion.Key pose=EditorMotion.sample(c,t,true);check(Math.abs(pose.x-.05)<.0001&&Math.abs(pose.y+.2)<.0001&&Math.abs(pose.scale-1.1)<.0001,"Preset placement moved over time "+id);}EditorProject.Clip copy=c.copy();check(copy.titleMotion==c.titleMotion&&copy.keys.isEmpty(),"Preset persistence "+id);}
   status(h,"Dragging an actual preset without creating keyframes");ui(h,()->{set(a,"project",project);set(a,"editing",true);set(a,"selectedCaption",0);set(a,"selectedOverlay",-1);set(a,"selectedTrack","Text");set(a,"tool","Text");set(a,"position",2500L);call(a,"showEditor");});Thread.sleep(700);ui(h,()->{drag((View)get(a,"placement"),35,-16);check(item.style.keys.isEmpty()&&Math.abs(item.style.textX)>.01,"Dragging preset created motion keys or failed to move");EditorMotion.Key p1=EditorMotion.sample(item.style,1500,true),p2=EditorMotion.sample(item.style,3500,true);check(Math.abs(p1.x-p2.x)<.0001&&Math.abs(p1.y-p2.y)<.0001,"Dragged preset snaps back");call(a,"addMotionKey");seek(a,4000);drag((View)get(a,"placement"),20,-8);check(item.style.keys.size()==2,"Explicit manual keyframing no longer works");});
   status(h,"Selecting a timeline diamond and deleting the selected key");EditorMotion.Key first=item.style.keys.get(0);ui(h,()->{EditorTimeline timeline=(EditorTimeline)get(a,"timeline");timeline.position(item.at+first.at);Method x=EditorTimeline.class.getDeclaredMethod("x",long.class),top=EditorTimeline.class.getDeclaredMethod("keyTop");x.setAccessible(true);top.setAccessible(true);float px=(Float)x.invoke(timeline,item.at+first.at),py=(Float)top.invoke(timeline)+5*a.getResources().getDisplayMetrics().density;long down=SystemClock.uptimeMillis();for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_UP}){MotionEvent e=MotionEvent.obtain(down,down,action,px,py,0);timeline.dispatchTouchEvent(e);e.recycle();}check(get(a,"selectedMotionKey")==first,"Timeline diamond was not selected");check((Long)get(timeline,"selectedKeyAt")==first.at,"Timeline selected highlight missing");});Thread.sleep(500);ui(h,()->{check(((View)get(a,"keyDeleteButton")).getVisibility()==View.VISIBLE,"Selected-key delete button is hidden");check("Keyframes".equals(get(a,"tool")),"Selecting a diamond did not open keyframe controls");});Bitmap screenshot=h.getUiAutomation().takeScreenshot();save(dir,"selected-key.png",screenshot);screenshot.recycle();ui(h,()->{seek(a,4500);((View)get(a,"keyDeleteButton")).performClick();check(item.style.keys.size()==1&&!item.style.keys.contains(first),"Delete followed playhead instead of selected key");call(a,"undo");check(current(a).captions.get(0).style.keys.size()==2,"Key deletion cannot undo");call(a,"redo");check(current(a).captions.get(0).style.keys.size()==1,"Key deletion cannot redo");EditorProject.Clip c=current(a).captions.get(0).style;EditorMotion.Key key=c.keys.get(0),pose=EditorMotion.sampleBase(c,key.at,true);select(a,current(a).captions.get(0).at+key.at);((View)get(a,"keyDeleteButton")).performClick();check(c.keys.isEmpty()&&c.titleMotion>0,"Last key deletion disabled preset animation");check(Math.abs(c.textX-pose.x)<.0001&&Math.abs(c.textY-pose.y)<.0001&&Math.abs(c.zoom-pose.scale)<.0001,"Deleting final key changed placement");call(a,"addMotionKey");call(a,"clearObjectKeys");});Thread.sleep(200);android.view.accessibility.AccessibilityNodeInfo root=h.getUiAutomation().getRootInActiveWindow();boolean clicked=false;for(var node:root.findAccessibilityNodeInfosByText("Remove keyframes"))if(node.isClickable()&&node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK)){clicked=true;break;}check(clicked,"Clear keyframes confirmation missing");Thread.sleep(250);ui(h,()->{check(current(a).captions.get(0).style.keys.isEmpty(),"Remove all failed");set(a,"position",2500L);seek(a,2500);call(a,"startExport");});
   status(h,"Exporting repositioned preset and checking stable placement");boolean[] busy={true};long until=SystemClock.elapsedRealtime()+90000;while(busy[0]&&SystemClock.elapsedRealtime()<until){Thread.sleep(250);ui(h,()->busy[0]=(Boolean)get(a,"exporting"));}String[] uri={null};ui(h,()->{check(!busy[0]&&get(a,"lastExport")!=null,"Preset export failed");uri[0]=get(a,"lastExport").toString();});MediaMetadataRetriever media=new MediaMetadataRetriever();try{media.setDataSource(a,Uri.parse(uri[0]));double[] centroid=new double[2];for(int i=0;i<2;i++){Bitmap frame=media.getFrameAtTime((i==0?2500:4500)*1000L,MediaMetadataRetriever.OPTION_CLOSEST);check(frame!=null,"Cannot decode preset export");long pixels=0,sumX=0;for(int y=0;y<frame.getHeight();y+=2)for(int x=0;x<frame.getWidth();x+=2){int c=frame.getPixel(x,y);if(Color.red(c)>150&&Color.green(c)<80&&Color.blue(c)<80){pixels++;sumX+=x;}}check(pixels>100,"Export missing social icon");centroid[i]=sumX/(double)pixels;save(dir,"export-"+i+".png",frame);frame.recycle();}check(Math.abs(centroid[0]-centroid[1])<2,"Preset snaps back in exported video");}finally{media.release();}result.putString("exportUri",uri[0]);result.putString("checks","PASS 88 independent preset placements, legacy generated-key migration, preservation of user keys, physical preset drag, manual keyframes, highlighted diamond selection, selected deletion, final-key pose, undo/redo, remove-all and stable MP4 placement");
  }finally{ui(h,a::finish);new File(a.getFilesDir(),"edit-projects/"+project.id+".json").delete();}
 }
}
